  background-color: var(--ytmusic-color-grey2) !important; }

ytmusic-detail-header-renderer {
  background-color: var(--ytmusic-color-black4) !important; }

.title.ytmusic-detail-header-renderer {
  color: var(--cust-ytmusic-light-text-1) !important; }

ytmusic-player-page {
  background-color: var(--ytmusic-color-black4) !important; }

ytmusic-data-bound-header-renderer {
  background-color: var(--cust-ytmusic-play-nav-color) !important; }

ytmusic-list-item-renderer {
  background-color: var(--ytmusic-color-black1) !important; }

ytmusic-responsive-list-item-renderer {
  background-color: var(--ytmusic-cust-dark-background) !important; }

ytmusic-player-queue-item {
  background-color: var(--ytmusic-cust-dark-background) !important; }

paper-tabs.ytmusic-player-page {
  --paper-tabs-selection-bar-color: var(
      --cust-ytmusic-medium-3
  ) !important ; }

#selectionBar.tp-yt-paper-tabs {
  border-bottom: 2px solid var(--cust-ytmusic-medium-3) !important; }

yt-formatted-string.byline.style-scope.ytmusic-player-queue-item {
  color: var(--cust-ytmusic-medium-1) !important; }

yt-formatted-string.duration.style-scope.ytmusic-player-queue-item {
  color: var(--cust-ytmusic-light-4) !important; }

/*color of the play bar background*/
ytmusic-player-bar {
  background: var(--cust-ytmusic-play-nav-color) !important; }

/*color of the progressbar slider*/
#progress-bar.ytmusic-player-bar {
  --paper-slider-active-color: var(
      --cust-ytmusic-progress-color
  ) !important ; }

#progress-bar.ytmusic-player-bar[focused],
ytmusic-player-bar:hover #progress-bar.ytmusic-player-bar {
  --paper-slider-knob-color: var(--cust-ytmusic-progress-color) !important;
  --paper-slider-knob-start-color: var(
      --cust-ytmusic-progress-color
  ) !important;
  --paper-slider-knob-start-border-color: var(
      --cust-ytmusic-progress-color
  ) !important ; }

/*volume slider*/
paper-slider#volume-slider {
  --paper-slider-container-color: var(--cust-ytmusic-light-4) !important;
  --paper-slider-active-color: var(
      --cust-ytmusic-tertiary-nav-button-color
  ) !important;
  --paper-slider-knob-color: var(
      --cust-ytmusic-tertiary-nav-button-color
  ) !important ; }

.volume-slider.ytmusic-player-bar, .expand-volume-slider.ytmusic-player-bar {
  --paper-slider-container-color: var(--cust-ytmusic-light-4) !important;
  --paper-slider-active-color: var(
      --cust-ytmusic-tertiary-nav-button-color
  ) !important;
  --paper-slider-knob-color: var(
      --cust-ytmusic-tertiary-nav-button-color
  ) !important ; }

/*play/pause/skip*/
paper-icon-button#play-pause-button {
  --iron-icon-fill-color: var(--cust-ytmusic-playbutton-color) !important ; }

tp-yt-iron-icon#icon {
  --iron-icon-fill-color: var(
      --cust-ytmusic-playbutton-color
  ) !important ; }

.left-controls.ytmusic-player-bar paper-icon-button.ytmusic-player-bar,
.left-controls.ytmusic-player-bar .spinner-container.ytmusic-player-bar,
.toggle-player-page-button.ytmusic-player-bar {
  --iron-icon-fill-color: var(
      --cust-ytmusic-tertiary-nav-button-color
  ) !important ; }

/*nav bar menu icon*/
.menu.ytmusic-player-bar {
  --iron-icon-fill-color: var(
      --cust-ytmusic-tertiary-nav-button-color
  ) !important ; }

/*nav bar right button icon colors*/
.right-controls-buttons.ytmusic-player-bar paper-icon-button.ytmusic-player-bar,
ytmusic-player-expanding-menu.ytmusic-player-bar
paper-icon-button.ytmusic-player-bar {
  --paper-icon-button_-_color: var(
      --cust-ytmusic-tertiary-nav-button-color
  ) !important ; }

.style-scope.yt-icon-button[aria-label="Add to playlist"] {
  color: var(--cust-ytmusic-tertiary-nav-button-color); }

/*color of titles*/
.title.ytmusic-carousel-shelf-basic-header-renderer,
.title.ytmusic-immersive-header-renderer,
.description.ytmusic-immersive-header-renderer {
  color: var(--ytmusic-color-white1) !important; }

/*Now playing circle*/
div.content-wrapper.style-scope.ytmusic-play-button-renderer {
  background: var(--cust-ytmusic-nowplaying-color) !important; }

/*subscribe button*/
ytmusic-subscribe-button-renderer {
  --ytmusic-subscribe-button-color: var(
      --cust-ytmusic-subscribe-color
  ) !important ; }

yt-button-renderer[is-paper-button] {
  background-color: var(--ytmusic-color-white1-alpha70) !important; }

paper-icon-button {
  --paper-icon-button_-_color: var(--ytmusic-color-white1) !important ; }

/*add to library button*/
ytmusic-data-bound-top-level-menu-item.ytmusic-data-bound-menu-renderer:not(:first-child
) {
  --yt-button-color: var(--ytmusic-color-white1) !important;
  border: 1px solid var(--ytmusic-color-white1) !important;
  border-radius: 5px !important; }

/*shuffle playlist button*/
yt-button-renderer.watch-button.ytmusic-menu-renderer {
  color: var(--ytmusic-color-white1) !important;
  background-color: var(--ytmusic-color-white1-alpha70) !important; }

/*edit playlist button*/
#top-level-buttons.ytmusic-menu-renderer
> .outline-button.ytmusic-menu-renderer,
.edit-playlist-button.ytmusic-menu-renderer,
ytmusic-toggle-button-renderer.ytmusic-menu-renderer {
  --yt-button-color: var(--ytmusic-color-white1) !important ; }

/*explicit badge*/
yt-icon.ytmusic-inline-badge-renderer {
  color: var(--cust-ytmusic-tertiary-nav-button-color) !important; }

/*headers that aren't links*/
.title.ytmusic-carousel-shelf-basic-header-renderer,
.title.ytmusic-immersive-header-renderer,
.description.ytmusic-immersive-header-renderer {
  color: var(--cust-ytmusic-header-text-1) !important; }

/*Songs header*/
.title.ytmusic-header-renderer {
  color: var(--cust-ytmusic-header-text-2) !important; }

yt-formatted-string.strapline.text.style-scope.ytmusic-carousel-shelf-basic-header-renderer {
  color: var(--cust-ytmusic-light-4) !important; }

/*Links*/
yt-formatted-string[has-link-only_]:not([force-default-style])
a.yt-simple-endpoint.yt-formatted-string {
  color: var(--cust-ytmusic-main-text-1) !important; }

yt-formatted-string[has-link-only_]:not([force-default-style])
a.yt-simple-endpoint.yt-formatted-string:hover {
  color: var(--cust-ytmusic-light-2) !important; }

/* scroll left and right carousel buttons */
.previous-items-button.ytmusic-carousel,
.next-items-button.ytmusic-carousel {
  background-color: var(--ytmusic-color-white1-alpha70) !important;
  color: var(--ytmusic-color-black1) !important; }

/* play button that pops up over album art to play immediately */
.content-wrapper.ytmusic-play-button-renderer,
ytmusic-play-button-renderer:hover
.content-wrapper.ytmusic-play-button-renderer,
ytmusic-play-button-renderer:focus
.content-wrapper.ytmusic-play-button-renderer {
  background: var(--ytmusic-color-white1-alpha70) !important;
  --ytmusic-play-button-icon-color: var(--ytmusic-color-black1) !important;
  --paper-spinner-color: var(--yt-spec-themed-blue) !important ; }

/* like button color */
paper-icon-button.ytmusic-like-button-renderer {
  color: var(--cust-ytmusic-medium-3) !important; }

/*settings highlighted*/
.category-menu-item.iron-selected.ytmusic-settings-page {
  background-color: var(--cust-ytmusic-medium-1) !important; }

/* some dropdown menus*/
.dropdown-content {
  background-color: var(--cust-ytmusic-dark-foreground) !important; }

/* fix the latest ambient update overriding the colors */
div.background-gradient.style-scope.ytmusic-browse-response {
  background-image: linear-gradient(to bottom, var(--cust-ytmusic-dark-background), var(--cust-ytmusic-dark-background)) !important; }

/* Right-click/context menu */
tp-yt-paper-listbox {
  background: #26233a !important;
  border: 1px solid rgba(255, 255, 255, 0.1) !important;
  border-radius: 2px; }
  tp-yt-paper-listbox .ytmusic-menu-popup-renderer:hover {
    background-color: rgba(255, 255, 255, 0.05) !important; }
  tp-yt-paper-listbox yt-icon {
    fill: var(--ytmusic-text-primary) !important; }
  tp-yt-paper-listbox yt-formatted-string {
    color: var(--ytmusic-text-primary) !important; }

body > nav[data-ytmd-main-panel] {
  background: #1f1d2e !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1) !important;
  color: var(--ytmusic-text-primary) !important;
  padding: 0; }
  body > nav[data-ytmd-main-panel] button {
    padding: 4px;
    height: 100%;
    width: 32px; }
    body > nav[data-ytmd-main-panel] button svg {
      stroke: var(--ytmusic-text-primary) !important;
      stroke-width: 1px !important;
      fill: var(--ytmusic-text-primary) !important; }
  body > nav[data-ytmd-main-panel] li {
    color: var(--ytmusic-text-primary) !important;
    font-size: 14px;
    font-weight: 400;
    padding: 4px;
    border-radius: 0; }

body > div > ul[data-ytmd-sub-panel="true"] {
  background: #26233a !important;
  border: 1px solid rgba(255, 255, 255, 0.1) !important;
  border-radius: 2px !important;
  color: var(--ytmusic-text-primary) !important;
  padding-left: 0;
  padding-right: 0; }
  body > div > ul[data-ytmd-sub-panel="true"] hr {
    height: 1px !important;
    color: rgba(255, 255, 255, 0.1) !important; }
  body > div > ul[data-ytmd-sub-panel="true"] li {
    height: 48px;
    border-radius: 0; }
    body > div > ul[data-ytmd-sub-panel="true"] li svg {
      color: var(--ytmusic-text-primary) !important; }
    body > div > ul[data-ytmd-sub-panel="true"] li span {
      color: var(--ytmusic-text-primary) !important;
      font-size: 14px;
      font-weight: 400; }
  body > div > ul[data-ytmd-sub-panel="true"] li[data-selected="false"]:hover {
    background-color: rgba(255, 255, 255, 0.05) !important; }
  body > div > ul[data-ytmd-sub-panel="true"] li[data-selected="true"] {
    background-color: rgba(255, 255, 255, 0.1) !important; }

/* Horizontal tabs e.g.: Library, Downloads */
/* When scrolling down, and it pins to top  */
